            continue
        identity = ('id', event['id']) if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        previous = selected.get(identity)
        if previous is None or revision >= previous[0]:
            selected[identity] = (revision, position, event)

    for _, _, event in selected.values():
        if event.get('void', False):
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        value = amount(event, data['rounding'])
        if event.get('kind') == 'refund':
            value = -value
        balances[key] += value

